python3 << 'EOF'
import csv
from collections import Counter

with open('market.csv', 'r') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

# Parse resolution dates
from datetime import datetime
def parse_date(s):
    for fmt in ('%Y-%m-%d', '%m/%d/%Y', '%Y-%m-%dT%H:%M:%S'):
        try:
            return datetime.strptime(s.strip(), fmt)
        except:
            pass
    return None

dates = []
for r in rows:
    d = parse_date(r['resolution_date'])
    dates.append(d)

# Group by month
months = Counter()
for d in dates:
    if d:
        months[d.strftime('%Y-%m')] += 1
    else:
        months['UNPARSEABLE'] += 1

print('=== Resolution dates by month ===')
for k in sorted(months.keys()):
    print(f'  {k}: {months[k]}')

print()
print('=== Earliest resolutions ===')
dated = [(d, r) for d, r in zip(dates, rows) if d]
dated.sort(key=lambda x: x[0])
for d, r in dated[:15]:
    print(f'  {d.strftime("%Y-%m-%d")} | {r["qid"]} | {r["title"][:80]}')
EOF

